s=s.replace('{sections.reduce((sum, key) => sum + form.findings[key].filter((item) => item.text.trim() && item.status !== "ok").length, 0)}', '{sections.reduce((sum, key) => sum + (form.findings[key] || []).filter((item) => item.text.trim() && item.status !== "ok").length, 0)}')
